//! Simulation with payloads.
//!
//! Each message a role sends is generated by the caller, checked against the JSON
//! Schema of its label, and recorded. A payload that does not match its schema
//! stops the run with [`SimulationError::Rejected`], so a mock peer never sends a
//! message the protocol's types do not allow.

use std::collections::BTreeMap;

use jsonschema::Validator;
use serde_json::Value;

use crate::simulate::run;
use crate::{GlobalProtocol, Outcome, Schemas, SimulationError};

/// A message sent during a simulation, with its payload.
#[derive(Debug, Clone, PartialEq)]
pub struct Message {
    /// The sending role.
    pub from: String,
    /// The receiving role.
    pub to: String,
    /// The message label.
    pub label: String,
    /// The payload, which matches the label's schema.
    pub payload: Value,
}

/// Run `protocol` like [`crate::simulate`], with each message's payload generated
/// by `payload(from, label)`. Returns the outcome and the messages sent, in order.
///
/// Every label the protocol sends needs a schema in `schemas`, and each payload is
/// checked against it before it is sent.
pub fn simulate_messages(
    protocol: &GlobalProtocol,
    schemas: &Schemas,
    policy: impl FnMut(usize) -> usize,
    max_steps: usize,
    mut payload: impl FnMut(&str, &str) -> Value,
) -> Result<(Outcome, Vec<Message>), SimulationError> {
    let mut validators: BTreeMap<String, Validator> = BTreeMap::new();
    if let Some(label) = schemas.missing(protocol).into_iter().next() {
        return Err(SimulationError::Schema {
            label,
            reason: "no schema is registered for this label".into(),
        });
    }
    let mut labels = Vec::new();
    crate::schema::collect_labels(protocol.statements(), &mut labels);
    for label in labels {
        let schema = schemas.get(&label).expect("missing labels were rejected");
        let validator =
            jsonschema::validator_for(schema).map_err(|error| SimulationError::Schema {
                label: label.clone(),
                reason: error.to_string(),
            })?;
        validators.insert(label, validator);
    }

    let mut messages = Vec::new();
    let outcome = run(protocol, policy, max_steps, &mut |from, to, label| {
        let value = payload(from, label);
        let validator = validators.get(label).expect("every label has a validator");
        let problems: Vec<String> = validator
            .iter_errors(&value)
            .map(|error| error.to_string())
            .collect();
        if !problems.is_empty() {
            return Err(problems.join("; "));
        }
        messages.push(Message {
            from: from.to_string(),
            to: to.to_string(),
            label: label.to_string(),
            payload: value,
        });
        Ok(())
    })?;
    Ok((outcome, messages))
}
